from datetime import datetime
from typing import Dict, Any, List

import boto3

from service.logs import logger
from util.date_time_util import build_standard_utc_timestamp_str


class DynamoDBQueryResponse:

    def __init__(self, items: List[Dict], last_evaluated_key: dict):
        self.items = items
        self.last_evaluated_key = last_evaluated_key


class DynamoDBService:

    def __init__(self):
        self.dynamodb = boto3.resource('dynamodb')
        self.table = self.dynamodb.Table("TodoAppTable")

    def query(self, key_condition_expression) -> DynamoDBQueryResponse:
        try:
            response = self.table.query(KeyConditionExpression=key_condition_expression)
            return DynamoDBQueryResponse(
                items=response.get('Items', []),
                last_evaluated_key=response.get('LastEvaluatedKey')
            )
        except Exception as e:
            logger.exception(e)

    def put_item(self, item: Dict[str, Any]):
        try:
            message = {
                "timestamp": build_standard_utc_timestamp_str(datetime.utcnow()),
                "log_type": "app_log",
                "event_type": "dynamodb_put_item",
                "data": item
            }
            print(message)
            self.table.put_item(Item=item)
        except Exception as e:
            logger.exception(e)

    def update_item(self, key: Dict[str, Any], updates: Dict[str, Any], item_entity_class_instance: Any):
        try:
            updates.pop('pk', None)
            updates.pop('sk', None)

            for update_key in updates.keys():
                if not hasattr(item_entity_class_instance, update_key):
                    raise ValueError(f"Key '{update_key}' is not an attribute of {self.__class__.__name__}")

            update_expression = "set " + ", ".join(
                f"{k}=:{k}" for k in updates.keys()
            )
            expression_attribute_values = {f":{k}": v for k, v in updates.items()}

            message = {
                "timestamp": build_standard_utc_timestamp_str(datetime.utcnow()),
                "log_type": "app_log",
                "event_type": "dynamodb_update_item",
                "data": {
                    'key': key,
                    'update_expression': update_expression,
                    'expression_attribute_values': expression_attribute_values
                }
            }
            print(message)
            self.table.update_item(
                Key=key,
                UpdateExpression=update_expression,
                ExpressionAttributeValues=expression_attribute_values,
                ReturnValues="UPDATED_NEW",
            )
        except Exception as e:
            logger.exception(e)
